function searchSuggest() {                                                   This routine is called on a key up;
  var str = document.getElementById("searchField").value;                    The value in the search field is first
  document.getElementById("searchField").className = "";                     extracted; if nothing is entered, do
  if (!str) return;                                                          nothing;
  document.getElementById("popups").innerHTML = "";
  for (const state of statesArray) {                              If starts with query, then we have a hit;
    if (state.nodeValue.toLowerCase().startsWith(str.toLowerCase())) {
      var tempDiv = document.createElement("div");
      tempDiv.innerHTML = state.nodeValue;
      tempDiv.onclick = makeChoice;
      tempDiv.className = "suggestions";                                        Add a state to the list of
      document.getElementById("popups").appendChild(tempDiv);                   possibilities
    }
  }                                                                                            Foundct is the number
  var foundCt = document.getElementById("popups").childNodes.length;                           of matches
  if (foundCt == 0) {
    document.getElementById("searchField").className = "error";
  } else if (foundCt == 1) {                Unique hit, place it in proper place
    document.getElementById("searchField").value =
    document.getElementById("popups").firstChild.innerHTML;
    document.getElementById("popups").innerHTML = "";
  }
}
function makeChoice(evt) {
